function errorReason(message){let match;if((match=message.match(/^\?OFDM PKT (\d+) .*CRC ERROR/)))return `エラー: OFDMパケットCRC不一致 #${match[1]}（FEC訂正待ち）`;if((match=message.match(/^\?OFDM FEC RECOVERY FAILED G(\d+) MISSING (\d+)/)))return `エラー: FEC訂正不能 G${match[1]}（欠損${match[2]}）`;if((match=message.match(/^\?V\d+ BLOCK\/SEQ (\d+) CRC32 ERROR/)))return `エラー: ブロックCRC不一致 SEQ ${match[1]}`;if(/FSK HEADER SUM ERROR/.test(message))return 'エラー: FSKヘッダSUM不一致';if(/FSK HEADER VERSION ERROR/.test(message))return 'エラー: FSKヘッダVERSION不正';if((match=message.match(/FSK SEQ (\d+) ERROR/)))return `エラー: FSK SEQ不正 ${match[1]}`;if(/FRAMING ERROR/.test(message))return 'エラー: FSKフレーミング不一致（再同期中）';if(/INCOMPLETE/.test(message))return 'エラー: ブロック受信未完了';return message.startsWith('ERROR')?`エラー: ${message.slice(5).trim()}`:null}
