function draw(data){const canvas=$('#scope'),pen=canvas.getContext('2d'),w=canvas.width,h=canvas.height,amp=h*.23,displayGain=1.6;pen.fillStyle='#030817';pen.fillRect(0,0,w,h);for(const [channel,samples,color,base,currentPeak,labelY] of [['l',data.left,'#50d8ff',h*.27,data.peakL,13],['r',data.right,'#ff3f9b',h*.73,data.peakR,h*.5+13]]){scopePeak[channel]=Math.max(scopePeak[channel],Math.abs(currentPeak||0));const heldPeak=scopePeak[channel];if(heldPeak){const pk=Math.min(heldPeak*displayGain,1)*amp;pen.strokeStyle='#f8d548';pen.lineWidth=1;pen.setLineDash([5,4]);pen.beginPath();pen.moveTo(0,base-pk);pen.lineTo(w,base-pk);pen.moveTo(0,base+pk);pen.lineTo(w,base+pk);pen.stroke();pen.setLineDash([]);pen.fillStyle='#f8d548';pen.font='11px ui-monospace,monospace';pen.fillText(`max ${db(heldPeak).toFixed(1)} dBFS`,6,labelY)}let phase=0;for(let i=0;i+1<samples.length;i++){const a=samples[i],b=samples[i+1];if(a<=0&&b>0){phase=i+(-a/(b-a));break}}pen.strokeStyle=color;pen.lineWidth=2;pen.beginPath();for(let index=0;index<samples.length;index++){const at=(phase+index)%samples.length,i0=Math.floor(at),frac=at-i0,i1=(i0+1)%samples.length,value=samples[i0]*(1-frac)+samples[i1]*frac,x=index*w/(samples.length-1),shown=Math.max(-1,Math.min(1,value*displayGain)),y=base-shown*amp;index?pen.lineTo(x,y):pen.moveTo(x,y)}pen.stroke()}}
