function db(value){return 20*Math.log10(Math.max(value,1e-6))}
const hold={l:-60,r:-60};
function meter(channel,rms,peak){const peakDb=db(peak),bar=$(`#meter-${channel}`),pct=v=>Math.max(0,Math.min(100,(v+60)*100/60));bar.style.width=`${pct(peakDb)}%`;bar.classList.toggle('clip',peak>=.988);$(`#db-${channel}`).textContent=`${db(rms).toFixed(1)} / ${peakDb.toFixed(1)} dB`;hold[channel]=Math.max(peakDb,hold[channel]-0.8);const hm=$(`#hold-${channel}`);if(hm)hm.style.left=`${pct(hold[channel])}%`}
function levelGuide(peak){const guide=$('#level-guide');if(peak>=.988){guide.textContent='CLIP — レベルを下げる';guide.style.color='#ff6680'}else if(peak>.708){guide.textContent='HOT — 少し下げる';guide.style.color='#f8d548'}else if(peak<.06){guide.textContent='LOW — レベルを上げる';guide.style.color='#f8d548'}else if(peak<.25){guide.textContent='OK — もう少し上げても可';guide.style.color='#50d8ff'}else{guide.textContent='GOOD';guide.style.color='#3fe0a0'}}
