function telemetry(message){$('#snr').textContent=`${message.snr.toFixed(1)} dB`;$('#tone').textContent=`${message.tone} Hz`;$('#tone-ratio').textContent=`${signed(message.toneRatio)} dB`;$('#balance').textContent=`${signed(message.balance)} dB`;$('#peaks').textContent=`${db(message.peakL).toFixed(1)} / ${db(message.peakR).toFixed(1)} dBFS`;$('#rms-pair').textContent=`${db(message.rmsL).toFixed(1)} / ${db(message.rmsR).toFixed(1)} dBFS`;$('#crest').textContent=`${message.crestL.toFixed(1)} / ${message.crestR.toFixed(1)} dB`;$('#dc').textContent=`${signed(message.dcL,4)} / ${signed(message.dcR,4)}`;$('#correlation').textContent=message.correlation.toFixed(3);$('#clips').textContent=`${message.clips} samples`}
