function markCells(fromKiB,toKiB,cls){const cells=blockCells();for(let i=fromKiB;i<toKiB&&i<cells.length;i++){const cell=cells[i],sector=grid.querySelector(`.course-sector[data-block="${i}"]`),c=cell.classList;c.remove('missing','receiving','complete','error');c.add(cls);if(sector){sector.classList.remove('missing','receiving','fec-recovering','complete','error');sector.classList.add(cls)}if(cls!=='receiving'){c.remove('fec-recovering');cell.style.removeProperty('--fill')}}}
