  if(message.type==='ofdm-packet'){const totalPackets=Math.ceil(message.total/(16*280))*22,diag=`C=${message.score.toFixed(3)} SNR=${message.snr.toFixed(1)} EVM=${(message.evm*100).toFixed(1)}% T=${message.timing.toFixed(2)} SWAP=${message.swap?'Y':'N'}`;$('#course-car')?.classList.remove('crc-spin');$('#ofdm-packets').textContent=`${message.crcOk} / ${totalPackets}`;$('#ofdm-correlation').textContent=message.score.toFixed(3);$('#ofdm-cfo').textContent=`${message.cfo.toFixed(1)} Hz / ${message.phase.toFixed(2)} rad`;$('#ofdm-quality').textContent=`${message.snr.toFixed(1)} dB / ${(message.evm*100).toFixed(1)}%`;$('#ofdm-crc').textContent=`${message.crcOk} OK / ${message.crcBad} NG`;$('#ofdm-drops').textContent=message.drops;$('#ofdm-recovered').textContent=`${receivedDataBytes} / ${message.total} bytes`;setPct(`${Math.min(100,Math.floor(receivedDataBytes*100/message.total))}%`);setStar('ofdm');if(crcNgRun){write(`OFDM CRC LOCK RECOVERED #${message.index} AFTER ${crcNgRun} NG`);crcNgRun=0}else if((message.index&31)===0)write(`OFDM PKT ${message.index} G${message.group} S${message.shard} CRC OK ${diag}`);return}
